export const QUICKBOOKS_CATEGORIES: Record<string, QuickBooksMethod[]> = QUICKBOOKS_METHODS.reduce(
  (acc, method) => {
    if (!acc[method.category]) {
      acc[method.category] = [];
    }
    acc[method.category].push(method);
    return acc;
  },
  {} as Record<string, QuickBooksMethod[]>,
);

export function getMethodsByCategory(category: string): QuickBooksMethod[] {
  return QUICKBOOKS_CATEGORIES[category] ?? [];
}
